messageValues.message:
={{ 
  'Translate the following job description into English.

' +
  'Job title: ' + $json.title + '

' +
  'Job description:
' + $json.description
}}

parameters.jsCode:
const jobs = $input.first().json.data;

return jobs.map(job => ({
  json: job
}));

const now = Math.floor(Date.now() / 1000);
const maxAge = 48 * 60 * 60;

return $input.all()
  .filter(item => {
    const createdAt = Number(item.json.created_at);

    if (!createdAt || Number.isNaN(createdAt)) {
      return false;
    }

    const age = now - createdAt;

    return age >= 0 && age <= maxAge;
  })
  .map(item => {
    const createdAt = Number(item.json.created_at);
    const ageHours = (now - createdAt) / 3600;

    return {
      json: {
        ...item.json,
        age_hours: Math.round(ageHours * 10) / 10
      }
    };
  });

const description = $json.description || '';

const text = description
  .toLowerCase()
  .replace(/<[^>]*>/g, ' ')
  .replace(/&[a-z]+;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const germanIndicators = [
  ' der ',
  ' die ',
  ' das ',
  ' den ',
  ' dem ',
  ' des ',
  ' und ',
  ' oder ',
  ' für ',
  ' mit ',
  ' auf ',
  ' eine ',
  ' einen ',
  ' einer ',
  ' einem ',
  ' suchen wir ',
  ' aufgaben ',
  ' anforderungen ',
  ' qualifikationen ',
  ' erfahrung ',
  ' kenntnisse ',
  ' bewerbung ',
  ' voraussetzungen ',
  ' wir bieten ',
  ' du hast ',
  ' du bist ',
  ' du verfügst ',
  ' deine ',
  ' dein ',
  ' deutsche ',
  ' deutschkenntnisse ',
  ' abgeschlossenes studium '
];

let germanScore = 0;

for (const indicator of germanIndicators) {
  if (text.includes(indicator)) {
    germanScore++;
  }
}

const hasImageOnlyContent =
  /<img[\s>]/i.test(description) &&
  text.replace(/find more.*$/i, '').trim().length < 150;

const insufficientText = text.length < 200;

let detected_language;

if (hasImageOnlyContent || insufficientText) {
  detected_language = 'Unknown';
} else if (germanScore >= 3) {
  detected_language = 'German';
} else {
  detected_language = 'English';
}

return {
  json: {
    ...$json,
    detected_language,
    german_score: germanScore,
    description_length: text.length,
    has_usable_text: !hasImageOnlyContent && !insufficientText
  }
};

const translatedText = $json.text || '';

const original = $('German Detection').item.json;

const descriptionEnglish =
  translatedText ||
  original.description ||
  '';

return {
  json: {
    job_title: original.title || '',
    company_name: original.company_name || '',
    location: original.location || '',

    description_original: original.description || '',
    description_english: descriptionEnglish,

    application_link: original.url || '',

    age_hours: original.age_hours ?? null,
    created_at: original.created_at ?? null,

    remote: original.remote ?? false,

    tags: original.tags || [],
    job_types: original.job_types || [],

    detected_language: original.detected_language || 'Unknown'
  }
};

return $input.all().map(item => {
  const job = item.json.job || item.json;

  return {
    json: {
      "Job Role": job.job_title || '',
      "Company Name": job.company_name || '',
      "Location": job.location || '',
      "Job Description": job.description_english || '',
      "Match Score": item.json.match_score || 0,
      "Recommendation": item.json.recommendation || '',
      "Matching Skills": (item.json.matching_qualifications || []).join('; '),
      "Missing Requirements": (item.json.missing_requirements || []).join('; '),
      "Language Concerns": (item.json.language_concerns || []).join('; '),
      "Posted Hours Ago": job.age_hours || '',
      "Application Link": job.application_link || ''
    }
  };
});

const cv = $('CV Keywords Extraction').first().json;

return $input.all().map(item => ({
  json: {
    cv_profile: cv,
    job: item.json
  }
}));
